mapper.sql:
p.status IN ('PUBLISHED', 'CLOSED')

  AND p.status = #{status}
  AND p.status = 'PUBLISHED'

AND p.category = #{categoryCode}

  AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))

t.status NOT IN ('DRAFT', 'PENDING_REVIEW', 'REJECTED')

  AND t.status = #{status}
  AND t.status NOT IN ('DISPUTED', 'CANCELLED')

AND t.category = #{categoryCode}
AND t.campus = #{campus}
AND t.reward_type = #{rewardType}

  AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR t.description LIKE CONCAT('%', #{keyword}, '%'))


  AND (t.location LIKE CONCAT('%', #{locationKeyword}, '%')
    OR t.delivery_location LIKE CONCAT('%', #{locationKeyword}, '%'))
